import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { Link } from 'react-router-dom';
import { PhysicsSection, UserStats } from '../types';

const StatsPage: React.FC = () => {
  const [stats, setStats] = useState<UserStats>({
    cardsStudied: 0,
    correctAnswers: 0,
    totalTime: 0,
    favoriteCards: []
  });

  // Для демонстрации загрузим временную статистику
  useEffect(() => {
    // В реальном приложении эти данные должны сохраняться в localStorage или на сервере
    const demoStats: UserStats = {
      cardsStudied: 47,
      correctAnswers: 32,
      totalTime: 7350, // в секундах (около 2 часов)
      favoriteCards: ['1', '3', '5'],
      lastSection: PhysicsSection.MECHANICS
    };

    // Имитация загрузки данных
    setTimeout(() => {
      setStats(demoStats);
    }, 500);
  }, []);

  // Форматирование времени в часы и минуты
  const formatTime = (seconds: number): string => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours} ч ${minutes} мин`;
  };

  // Расчет точности ответов в процентах
  const calculateAccuracy = (): number => {
    if (stats.cardsStudied === 0) return 0;
    return Math.round((stats.correctAnswers / stats.cardsStudied) * 100);
  };

  return (
    <PageContainer>
      <PageHeader>
        <h1>Статистика обучения</h1>
        <PageDescription>
          Отслеживайте свой прогресс и улучшайте эффективность обучения
        </PageDescription>
      </PageHeader>

      <StatsGrid>
        <StatCard>
          <StatIcon>📚</StatIcon>
          <StatTitle>Изучено карточек</StatTitle>
          <StatValue>{stats.cardsStudied}</StatValue>
        </StatCard>

        <StatCard>
          <StatIcon>✅</StatIcon>
          <StatTitle>Правильных ответов</StatTitle>
          <StatValue>{stats.correctAnswers}</StatValue>
        </StatCard>

        <StatCard>
          <StatIcon>📊</StatIcon>
          <StatTitle>Точность</StatTitle>
          <StatValue>{calculateAccuracy()}%</StatValue>
        </StatCard>

        <StatCard>
          <StatIcon>⏱️</StatIcon>
          <StatTitle>Время обучения</StatTitle>
          <StatValue>{formatTime(stats.totalTime)}</StatValue>
        </StatCard>
      </StatsGrid>

      <SectionTitle>Рекомендации</SectionTitle>
      
      <RecommendationsContainer>
        <RecommendationCard>
          <RecommendationIcon>🔄</RecommendationIcon>
          <RecommendationContent>
            <RecommendationTitle>Повторите раздел</RecommendationTitle>
            <RecommendationText>
              {stats.lastSection 
                ? `Вы хорошо справляетесь с разделом "${stats.lastSection}". Продолжайте изучать эту тему для закрепления.` 
                : 'Начните с изучения раздела "Механика" для формирования базовых знаний.'}
            </RecommendationText>
            <RecommendationButton 
              to={`/section/${stats.lastSection || PhysicsSection.MECHANICS}`}
            >
              Перейти к разделу
            </RecommendationButton>
          </RecommendationContent>
        </RecommendationCard>

        <RecommendationCard>
          <RecommendationIcon>🎮</RecommendationIcon>
          <RecommendationContent>
            <RecommendationTitle>Попробуйте игровой режим</RecommendationTitle>
            <RecommendationText>
              Для лучшего запоминания материала используйте игровой режим с таймером и подсчетом очков.
            </RecommendationText>
            <RecommendationButton to="/cards?mode=game">
              Начать игру
            </RecommendationButton>
          </RecommendationContent>
        </RecommendationCard>
      </RecommendationsContainer>

      <SectionTitle>История активности</SectionTitle>
      
      <ActivityHistory>
        <ActivityChartPlaceholder>
          <ChartMessage>
            Здесь будет отображаться график вашей активности за последние 30 дней
          </ChartMessage>
        </ActivityChartPlaceholder>

        <RecentActivity>
          <h3>Недавние действия</h3>
          <ActivityList>
            <ActivityItem>
              <ActivityDate>Сегодня, 14:32</ActivityDate>
              <ActivityDescription>
                Изучено 12 карточек в разделе "Механика"
              </ActivityDescription>
            </ActivityItem>
            <ActivityItem>
              <ActivityDate>Вчера, 18:45</ActivityDate>
              <ActivityDescription>
                Добавлено 3 карточки в избранное
              </ActivityDescription>
            </ActivityItem>
            <ActivityItem>
              <ActivityDate>3 дня назад</ActivityDate>
              <ActivityDescription>
                Получено 85% правильных ответов в тестовом режиме
              </ActivityDescription>
            </ActivityItem>
            <ActivityItem>
              <ActivityDate>7 дней назад</ActivityDate>
              <ActivityDescription>
                Начато изучение раздела "Электродинамика"
              </ActivityDescription>
            </ActivityItem>
          </ActivityList>
        </RecentActivity>
      </ActivityHistory>
    </PageContainer>
  );
};

